export const getGetReferenceGuideUrl = () => {




  return `/api/reference`
}

/**
 * @summary Get category, indicator, and dataset reference information
 */
export const getReferenceGuide = async ( options?: Parameters<typeof customFetch>[1]): Promise<ReferenceGuide> => {

  return customFetch<ReferenceGuide>(getGetReferenceGuideUrl(),
  {
    ...options,
    method: 'GET'


  }
);}





export const getGetReferenceGuideQueryKey = () => {
    return [
    `/api/reference`
    ] as const;
    }


export const getGetReferenceGuideQueryOptions = <TData = Awaited<ReturnType<typeof getReferenceGuide>>, TError = ErrorType<unknown>>( options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getReferenceGuide>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetReferenceGuideQueryKey();



    const queryFn: QueryFunction<Awaited<ReturnType<typeof getReferenceGuide>>> = ({ signal }) => getReferenceGuide({ signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getReferenceGuide>>, TError, TData> & { queryKey: QueryKey }
}

export type GetReferenceGuideQueryResult = NonNullable<Awaited<ReturnType<typeof getReferenceGuide>>>
export type GetReferenceGuideQueryError = ErrorType<unknown>


/**
 * @summary Get category, indicator, and dataset reference information
 */

export function useGetReferenceGuide<TData = Awaited<ReturnType<typeof getReferenceGuide>>, TError = ErrorType<unknown>>(
  options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getReferenceGuide>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getGetReferenceGuideQueryOptions(options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







